#!/usr/bin/env node
// Generates per-host plugin manifests from the single source of truth.
//
// Source of truth, per plugin:
//   plugins/<name>/plugin.json   (Agent Plugins 1.0 manifest)
//   plugins/<name>/mcp.json      (Agent Plugins 1.0 MCP config, optional)
//
// Generated (never hand-edit):
//   plugins/<name>/.claude-plugin/plugin.json   (Claude Code manifest)
//   plugins/<name>/.mcp.json                    (Claude Code / Copilot MCP config)
//
// Usage:
//   node scripts/generate-manifests.mjs           # write generated files
//   node scripts/generate-manifests.mjs --check   # fail if generated files are stale
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const GENERATED_NOTE = "GENERATED by scripts/generate-manifests.mjs — edit plugin.json / mcp.json instead";

function render(obj) {
  return JSON.stringify(obj, null, 2) + "\n";
}

function claudeManifest(src) {
  const out = {};
  for (const key of ["name", "version", "description", "author", "homepage", "repository", "license", "keywords"]) {
    if (src[key] !== undefined) out[key] = src[key];
  }
  out.metadata = { generated: GENERATED_NOTE }; // Claude Code ignores metadata
  return out;
}

function claudeMcp(src) {
  // Same servers; Claude Code / Copilot read .mcp.json without a $schema field.
  // No comment key here — MCP config parsers may be strict about unknown fields.
  return { mcpServers: src.mcpServers };
}

let stale = [];
const pluginsDir = join(root, "plugins");
for (const name of readdirSync(pluginsDir).sort()) {
  const dir = join(pluginsDir, name);
  const srcManifestPath = join(dir, "plugin.json");
  if (!existsSync(srcManifestPath)) continue; // placeholder plugin (README only)

  const src = JSON.parse(readFileSync(srcManifestPath, "utf8"));
  const targets = [
    [join(dir, ".claude-plugin", "plugin.json"), render(claudeManifest(src))],
  ];
  const mcpPath = join(dir, "mcp.json");
  if (existsSync(mcpPath)) {
    const mcp = JSON.parse(readFileSync(mcpPath, "utf8"));
    targets.push([join(dir, ".mcp.json"), render(claudeMcp(mcp))]);
  }

  for (const [path, content] of targets) {
    const current = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (current === content) continue;
    if (check) {
      stale.push(path);
    } else {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, content);
      console.log(`wrote ${path.slice(root.length + 1)}`);
    }
  }
}

if (check && stale.length) {
  console.error("Generated manifests are stale. Run: node scripts/generate-manifests.mjs");
  for (const p of stale) console.error(`  ${p.slice(root.length + 1)}`);
  process.exit(1);
}
if (check) console.log("generated manifests are in sync");
